void out_q_remove( Out_Q out_q , Out_Func out_func , Boolean do_reset )
{
    Fifo_Node *curr , *temp  ; 
		
	for( curr = out_q->fifo_exec->rhs ; curr != out_q->fifo_exec ; curr = curr->rhs )
	{		
		if(((Out_Q_Node*)curr)->out->out_func == out_func )
		{
			((Out_Q_Node*)curr)->req_done = TRUE     ; 				
			
			((Out_Q_Node*)curr)->do_reset = do_reset ; 				
		};					 
	}	
}

